/* Executive reports: narrative, evidence charts and optional record-card appendix. */
const professionalReportOptions={appendix:true,details:false};
function reportAnalysis(rows,filters=reportSelection()){
 const sum=k=>rows.reduce((s,r)=>s+(typeof r[k]==='number'?r[k]:0),0),avg=k=>{const values=rows.map(r=>r[k]).filter(v=>typeof v==='number'&&Number.isFinite(v));return values.length?values.reduce((a,b)=>a+b,0)/values.length:null},count=s=>rows.filter(r=>r.status===s).length;
 const n=rows.length,sites=new Set(rows.map(r=>r.factory)).size,supplied=rows.filter(r=>r.source!=='Illustrative').length;
 let metrics=[['Filtered records',n,'Matching your selected filters'],['Factories represented',sites,'Within this report'],['Supplied records',supplied,'Imported or gateway data'],['Illustrative records',n-supplied,'Illustrative records']],attention=0,comparison='Matching records',unit='records',aggregate=list=>list.length,action='Review the filtered evidence with the relevant factory owner.';
 if(['production','packaging'].includes(filters.type)){const target=sum('target_units'),output=sum('produced_units');metrics=[['Produced units',nfmt(output),'Filtered lines'],['Plan attainment',target?(100*output/target).toFixed(1)+'%':'—','Total output ÷ total plan'],['Average utilization',avg('utilization_percent')==null?'—':avg('utilization_percent').toFixed(1)+'%','Unweighted line average'],['Lines not running',rows.filter(r=>r.status!=='Running').length,'Stopped or changing over']];attention=rows.filter(r=>r.status!=='Running'||r.produced_units<r.target_units).length;comparison='Production output by factory';unit='units';aggregate=list=>list.reduce((s,r)=>s+r.produced_units,0);action='Review non-running lines and plan shortfalls before confirming delivery commitments.'}
 if(filters.type==='maintenance'){attention=rows.filter(r=>r.health_percent<90).length;metrics=[['Assets reviewed',n,'Filtered asset records'],['Average condition',avg('health_percent')==null?'—':avg('health_percent').toFixed(1)+'%','Unweighted asset average'],['Health below 90%',attention,'Condition review threshold'],['Assigned work orders',count('Assigned'),'Current supplied or illustrative state']];comparison='Average asset health by factory';unit='%';aggregate=list=>list.reduce((s,r)=>s+r.health_percent,0)/list.length;action='Review low-health assets, current measurements and qualified maintenance availability.'}
 if(filters.type==='alarms'){attention=rows.filter(r=>r.status!=='Resolved').length;metrics=[['Alarm records',n,'Filtered alert records'],['Unresolved',attention,'Open or acknowledged'],['High severity',rows.filter(r=>r.severity==='High').length,'Includes resolved records if selected'],['Resolved',count('Resolved'),'Current record status']];comparison='Unresolved alarms by factory';unit='alarms';aggregate=list=>list.filter(r=>r.status!=='Resolved').length;action='Prioritize unresolved high-severity alarms and check their recorded business impact.'}
 if(filters.type==='batches'){attention=count('Held');metrics=[['Batches reviewed',n,'Filtered batch records'],['Running',count('Running'),'Current batch state'],['Held',attention,'Requires review'],['Complete',count('Complete'),'Source-confirmed or illustrative state']];comparison='Held batches by factory';unit='batches';aggregate=list=>list.filter(r=>r.status==='Held').length;action='Review held-batch evidence before resuming execution or promising downstream availability.'}
 if(filters.type==='workforce'){attention=count('Expired');metrics=[['People reviewed',n,'Filtered workforce records'],['Current qualifications',count('Current'),'As reported by the roster'],['Expired qualifications',attention,'Assignment eligibility review'],['Factories represented',sites,'Within this report']];comparison='Expired qualifications by factory';unit='people';aggregate=list=>list.filter(r=>r.status==='Expired').length;action='Verify required skills and qualification validity before assigning maintenance work.'}
 if(['quality','facility'].includes(filters.type)){attention=rows.filter(r=>r.status==='Review'||(typeof r.value==='number'&&((typeof r.minimum==='number'&&r.value<r.minimum)||(typeof r.maximum==='number'&&r.value>r.maximum)))).length;metrics=[['Checks / readings',n,'Filtered measurement records'],['Within range',count('Within range'),'Against supplied limits'],['Requires review',attention,'Outside reported limits'],['Other states',n-count('Within range')-attention,'Cycle states or illustrative summaries']];comparison='Readings requiring review by factory';unit='readings';aggregate=list=>list.filter(r=>r.status==='Review'||(typeof r.value==='number'&&((typeof r.minimum==='number'&&r.value<r.minimum)||(typeof r.maximum==='number'&&r.value>r.maximum)))).length;action='Investigate out-of-range measurements with their source limits and approved procedures; this report does not authorize release.'}
 if(filters.type==='supplychain'){attention=rows.filter(r=>r.at_risk==='Yes').length;metrics=[['Customer orders',rows.filter(r=>r.entity_type==='Customer order').length,'Filtered order records'],['Orders at risk',attention,'Source risk flag'],['Materials reviewed',rows.filter(r=>r.entity_type==='Material').length,'Inventory records'],['Factories represented',sites,'Summary rows may be illustrative data']];comparison='At-risk orders by factory';unit='orders';aggregate=list=>list.filter(r=>r.at_risk==='Yes').length;action='Review flagged customer orders alongside material coverage and the latest recovery plan.'}
 if(filters.type==='business'){const values=key=>rows.filter(r=>r.measure===key&&typeof r.value==='number').map(r=>r.value),mean=key=>{const v=values(key);return v.length?(v.reduce((a,b)=>a+b,0)/v.length).toFixed(1)+'%':'Not supplied'},total=key=>{const v=values(key);return v.length?nfmt(v.reduce((a,b)=>a+b,0)):'Not supplied'};metrics=[['First-pass quality',mean('quality'),'Unweighted factory average'],['On-time delivery',mean('delivery'),'Unweighted factory average'],['Cost of poor quality',total('cost')+(values('cost').length?' EGP k':''),'Sum of filtered factory values'],['Lost production time',total('downtime')+(values('downtime').length?' h':''),'Sum of filtered factory values']];attention=rows.filter(r=>(r.measure==='quality'&&r.value<98)||(r.measure==='delivery'&&r.value<93)||(r.measure==='legal'&&r.value>0)).length;action='Review quality below 98%, delivery below 93% and open legal issues alongside reported costs and downtime.'}
 if(filters.type==='sustainability'){metrics=[['Energy consumption',rows.some(r=>r.energy_mwh!=null)?nfmt(sum('energy_mwh'))+' MWh':'Not supplied','Sum of supplied intervals'],['Carbon emissions',rows.some(r=>r.emissions_tco2e!=null)?nfmt(sum('emissions_tco2e'))+' tCO2e':'Not supplied','Sum of supplied intervals'],['Average water reuse',avg('water_reuse_percent')==null?'—':avg('water_reuse_percent').toFixed(1)+'%','Unweighted interval average'],['Intervals / summaries',n,'Filtered source profile']];comparison='Records by factory';action='Compare resource demand with production volumes before concluding that efficiency has changed.'}
 const grouped=[...new Set(rows.map(r=>r.factory))].map(name=>({name,value:aggregate(rows.filter(r=>r.factory===name))})),statuses=[...new Set(rows.map(r=>r.status||'Not supplied'))].map(name=>({name,value:rows.filter(r=>(r.status||'Not supplied')===name).length}));
 const dates=rows.map(r=>r.observed_at).filter(v=>v&&Number.isFinite(Date.parse(v))).sort((a,b)=>Date.parse(a)-Date.parse(b)),stale=rows.filter(r=>r.observed_at&&Date.now()-Date.parse(r.observed_at)>900000).length;
 return {metrics,attention,comparison,unit,grouped,statuses,sites,supplied,demo:n-supplied,stale,dates,action,summary:`This ${reportTypes[filters.type].toLowerCase()} report covers ${n} matching records across ${sites} ${sites===1?'factory':'factories'} for ${filters.period.toLowerCase()}. ${attention?attention+' records meet the review criteria below.':'No records meet the selected report’s review criteria; this is not an assurance of overall factory performance.'}`};
}
function reportBarChart(items,label,unit){const max=Math.max(1,...items.map(r=>r.value));return `<svg viewBox="0 0 740 175" role="img" aria-label="${escapeHTML(label)}"><title>${escapeHTML(label)}</title>${items.map((r,i)=>{const y=20+i*38,w=410*r.value/max;return `<text x="0" y="${y+16}" font-size="12" fill="currentColor">${escapeHTML(r.name)}</text><rect x="225" y="${y}" width="410" height="23" rx="5" fill="#dce9e6"/><rect x="225" y="${y}" width="${w}" height="23" rx="5" fill="#248776"><title>${escapeHTML(r.name)}: ${nfmt(r.value)} ${escapeHTML(unit)}</title></rect><text x="645" y="${y+16}" font-size="12" fill="currentColor">${nfmt(+r.value.toFixed(1))}${unit==='%'?'%':''}</text>`}).join('')}</svg>`}
function reportStatusChart(items){const colors=['#248776','#d29b43','#778db2','#be6a78','#8d7eb0','#82948e'],total=items.reduce((s,r)=>s+r.value,0);let offset=0;const display=items.length>6?[...items.slice(0,5),{name:'Other states',value:items.slice(5).reduce((s,r)=>s+r.value,0)}]:items;return `<svg viewBox="0 0 470 175" role="img" aria-label="Record status distribution"><title>Status distribution of filtered records</title><circle cx="82" cy="85" r="53" fill="none" stroke="#e0eae7" stroke-width="18"/>${display.map((r,i)=>{const length=total?r.value/total*333.01:0,svg=`<circle cx="82" cy="85" r="53" fill="none" stroke="${colors[i]}" stroke-width="18" stroke-dasharray="${length} ${333.01-length}" stroke-dashoffset="${-offset}" transform="rotate(-90 82 85)"><title>${escapeHTML(r.name)}: ${r.value} records</title></circle>`;offset+=length;return svg}).join('')}<text x="82" y="84" text-anchor="middle" fill="currentColor" font-size="25" font-weight="700">${total}</text><text x="82" y="103" text-anchor="middle" fill="currentColor" font-size="10">records</text>${display.map((r,i)=>`<circle cx="170" cy="${26+i*25}" r="5" fill="${colors[i]}"/><text x="184" y="${30+i*25}" fill="currentColor" font-size="12">${escapeHTML(r.name.length>32?r.name.slice(0,30)+'…':r.name)} · ${r.value}<title>${escapeHTML(r.name)}</title></text>`).join('')}</svg>`}
function executiveReportPreview(rows,filters=reportSelection()){if(!rows.length)return '<div class="executive-empty">No matching records. Adjust the filters to build your report.</div>';const a=reportAnalysis(rows,filters);return `<div class="executive-metrics">${a.metrics.map(([label,value,note])=>`<article><small>${escapeHTML(label)}</small><strong>${escapeHTML(value)}</strong><span>${escapeHTML(note)}</span></article>`).join('')}</div><div class="executive-charts"><section><h3>${escapeHTML(a.comparison)}</h3><small>${escapeHTML(a.unit)}</small>${reportBarChart(a.grouped,a.comparison,a.unit)}</section><section><h3>Status distribution</h3><small>Filtered records by current state</small>${reportStatusChart(a.statuses)}</section></div><div class="executive-insight"><strong>Management focus</strong><span>${escapeHTML(a.action)}</span><small>${a.demo} illustrative records · ${a.supplied} supplied records${a.stale?' · '+a.stale+' supplied records older than 15 minutes':''}</small></div>`}
function buildProfessionalReport(rows,filters=reportSelection(),options=professionalReportOptions){const a=reportAnalysis(rows,filters),e=escapeHTML,generated=new Date().toISOString(),generatedLabel=new Intl.DateTimeFormat('en-GB',{timeZone:'Africa/Cairo',dateStyle:'medium',timeStyle:'short'}).format(new Date())+' (Cairo)',scope=filters.factory<0?'All factories':factories[filters.factory].name,identity=r=>r.work_order||r.asset||r.alarm||r.batch||r.technician||r.item||r.measure||r.interval||r.product||'Record',excluded=['factory','period','source','source_name','observed_at'];return `<!doctype html><html><head><meta charset="utf-8"><title>Life Science ${e(reportTypes[filters.type])} report - ${e(filters.period)}</title><style>@page{size:A4 landscape;margin:12mm}*{box-sizing:border-box}body{margin:0;font:11px 'Segoe UI',Arial,sans-serif;color:#21343c;background:#fff;-webkit-print-color-adjust:exact;print-color-adjust:exact}.report-cover{border-top:5px solid #248776;padding-top:13px}.brand{font-size:10px;letter-spacing:2px;font-weight:700;color:#248776}.report-heading{display:flex;justify-content:space-between;gap:25px;align-items:start;margin:12px 0}h1{font-size:28px;letter-spacing:-.7px;margin:0 0 6px}h2{font-size:17px;margin:0 0 10px}h3{font-size:12px;margin:0 0 4px}.scope{color:#5b6f76;font-size:11px}.issue{font-size:10px;line-height:1.7;text-align:right;color:#5b6f76}.summary{font-size:12px;line-height:1.6;margin:12px 0 15px;max-width:950px}.filter-strip{display:flex;gap:20px;background:#f1f5f4;border-radius:7px;padding:9px 12px;font-size:10px;margin-bottom:14px}.executive-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:0 0 15px}.executive-metrics article{padding:12px 14px;border:1px solid #d8e4df;border-radius:9px;background:#f7faf9;break-inside:avoid}.executive-metrics small{display:block;color:#526a72;font-size:10px}.executive-metrics strong{display:block;font-size:25px;margin:6px 0;color:#1b6256}.executive-metrics span{font-size:9px;color:#63777e}.executive-charts{display:grid;grid-template-columns:1.3fr 1fr;gap:14px}.executive-charts section{padding:12px 14px;border:1px solid #d8e4df;border-radius:9px;break-inside:avoid}.executive-charts small{font-size:9px;color:#63777e}.executive-charts svg{display:block;width:100%;height:155px;margin-top:5px}.executive-insight{margin-top:14px;border-left:4px solid #d29b43;padding:11px 13px;background:#fbf7ed;border-radius:5px;break-inside:avoid}.executive-insight strong{display:block;font-size:11px;margin-bottom:5px}.executive-insight span{display:block;line-height:1.5}.executive-insight small{display:block;margin-top:6px;color:#6f6a5b}.provenance{display:flex;justify-content:space-between;gap:20px;border-top:1px solid #d8e4df;margin-top:14px;padding-top:9px;font-size:9px;line-height:1.5;color:#61757c}.appendix{break-before:page;padding-top:6px}.appendix>p{color:#61757c;line-height:1.5}.record-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.record-card{border:1px solid #d8e4df;border-radius:8px;padding:13px;break-inside:avoid;min-width:0}.record-top{display:flex;justify-content:space-between;gap:10px;align-items:start;border-bottom:1px solid #e1eae6;padding-bottom:8px}.record-top strong{font-size:13px;overflow-wrap:anywhere}.tag{font-size:9px;padding:4px 7px;border-radius:20px;background:#eaf4ef;white-space:nowrap}.record-meta{font-size:9px;color:#61757c;margin:7px 0;overflow-wrap:anywhere}.record-card dl{display:grid;grid-template-columns:1fr 1fr;gap:8px 15px;margin:10px 0 0}.record-card dl div{min-width:0}.record-card dt{font-size:9px;text-transform:capitalize;color:#61757c}.record-card dd{font-size:11px;margin:3px 0 0;overflow-wrap:anywhere}.appendix-footer{font-size:9px;color:#61757c;margin-top:15px}@media screen{body{max-width:1200px;margin:30px auto;padding:0 25px 35px}.appendix{margin-top:35px}}@media print{.report-cover{break-inside:avoid}a{color:inherit;text-decoration:none}}</style></head><body><section class="report-cover"><div class="brand">LIFE SCIENCE ENTERPRISE / MANAGEMENT REPORT</div><header class="report-heading"><div><h1>${e(reportTypes[filters.type])} performance report</h1><div class="scope">${e(scope)} · ${e(filters.period)}</div></div><div class="issue">Generated ${e(generatedLabel)}<br>${rows.length} matching records · ${a.sites} factories</div></header><div class="filter-strip"><span>Status: ${e(filters.status)}</span><span>Source: ${e(filters.source)}</span><span>Search: ${e(filters.search||'None')}</span></div><p class="summary">${e(a.summary)}</p>${executiveReportPreview(rows,filters)}<div class="provenance"><span>Evidence: ${a.supplied} supplied / ${a.demo} illustrative records. Rates marked average are unweighted; records are not independently verified.</span><span>${a.dates.length?'Source timestamps: '+e(a.dates[0])+' to '+e(a.dates.at(-1)):'No source measurement timestamps supplied.'}<br>Period snapshots do not reconstruct historical trends.</span></div></section>${options.appendix?`<section class="appendix"><div class="brand">SUPPORTING EVIDENCE</div><h2>Detailed record cards</h2><p>All ${rows.length} filtered records are included below. Each card identifies its factory, period, data source and reported state.</p><div class="record-grid">${rows.map((r,i)=>`<article class="record-card"><div class="record-top"><strong>${i+1}. ${e(identity(r))}</strong><span class="tag">${e(r.status||'Not supplied')}</span></div><div class="record-meta">${e(r.factory)} · ${e(r.period)} · ${e(r.source)}<br>${e(r.source_name)}${r.observed_at?' · '+e(r.observed_at):' · no source timestamp'}</div><dl>${Object.entries(r).filter(([key])=>!excluded.includes(key)).map(([key,value])=>`<div><dt>${e(key.replaceAll('_',' '))}</dt><dd>${e(value??'Not supplied')}</dd></div>`).join('')}</dl></article>`).join('')}</div><div class="appendix-footer">Generated ${e(generatedLabel)} · Filtered evidence for management review. This report is not equipment execution confirmation or quality-release authorization.</div></section>`:''}</body></html>`}
printFilteredReport=function(){const rows=filteredReportRows();if(rows.length)printHTML(buildProfessionalReport(rows))};
function previewProfessionalReport(){const rows=filteredReportRows();if(!rows.length)return;const popup=window.open('','_blank');if(!popup){openModal('Preview blocked','Allow popups to open the formatted report preview.');return}popup.document.write(buildProfessionalReport(rows));popup.document.close();popup.focus()}
const reportsBeforeProfessional=reportsView;reportsView=function(){const box=document.createElement('div');box.innerHTML=reportsBeforeProfessional();const workspace=box.querySelector('.report-workspace'),table=box.querySelector('.report-table'),rows=filteredReportRows();box.querySelector('.report-summary span:last-child').textContent='Charts summarize every matching record. Detailed record cards are optional in PDF.';const actions=box.querySelector('.panelhead>.actions');actions.insertAdjacentHTML('afterbegin',`<button onclick="previewProfessionalReport()" ${rows.length?'':'disabled'}>Preview report</button>`);const options=document.createElement('div');options.className='professional-report-options';options.innerHTML=`<label><input type="checkbox" ${professionalReportOptions.appendix?'checked':''} onchange="professionalReportOptions.appendix=this.checked"> Include detailed record cards in PDF</label><button onclick="professionalReportOptions.details=!professionalReportOptions.details;render()">${professionalReportOptions.details?'Show executive preview':'Inspect raw records'}</button>`;workspace.insertBefore(options,table);if(!professionalReportOptions.details){const preview=document.createElement('div');preview.className='executive-preview';preview.innerHTML=executiveReportPreview(rows);table.replaceWith(preview)}return box.innerHTML};
render();
